// Generated by tools/animations/export-original-clips.ts; regenerate instead of editing.
// Each fighter's key-thinning row (#314) is in key-thin/<slug>.tsv, which a re-export rewrites alone; this index changes only when a fighter is added.
import { readFileSync } from "node:fs";
import { join } from "node:path";

export const KEY_THIN_FIGHTERS: readonly string[] = [
  "illidan",
  "blademaster",
  "mountain-king",
  "lich",
  "dreadlord",
  "pit-lord",
  "beastmaster",
  "lich-king",
  "jaina-proudmoore",
  "sylvanas-windrunner",
  "chen-stormstout",
  "peon",
  "murloc",
  "grom-hellscream",
  "malfurion-stormrage",
  "medivh",
  "thrall",
  "kael'thas-sunstrider",
  "rifleman",
  "warden",
  "anub'arak",
  "forsaken-paladin",
  "cairne-bloodhoof",
  "kobold",
  "goblin-tinker",
  "shadow-hunter",
];

/** The whole table: the comment and header once, then each listed fighter's row. */
export function keyThinTable(): string {
  const files = KEY_THIN_FIGHTERS.map(slug => readFileSync(join(import.meta.dir, "key-thin", `${slug}.tsv`), "utf8").trimEnd().split("\n"));
  return [...(files[0] ?? []).slice(0, 2), ...files.flatMap(lines => lines.slice(2))].join("\n") + "\n";
}
